#import "AdminView.h"
@interface AdminView()
@property NSDictionary*config;@property NSArray*cookies;@property NSString*route;@property WKWebView*web;@property BOOL didClose;
@end
@implementation AdminView
-(instancetype)initWithConfig:(NSDictionary*)config cookies:(NSArray*)cookies route:(NSString*)route{if((self=[super init])){_config=config;_cookies=cookies;_route=route;}return self;}
-(BOOL)isMiFi{return [_config[@"mifi"]boolValue];}
-(void)viewDidLoad{[super viewDidLoad];self.title=[self isMiFi]?@"MiFi 完整管理":@"CPE 完整管理";self.view.backgroundColor=UIColor.systemBackgroundColor;self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"完成" style:UIBarButtonItemStyleDone target:self action:@selector(close)];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemRefresh target:self action:@selector(startLoad)];WKWebViewConfiguration*c=[WKWebViewConfiguration new];c.websiteDataStore=[WKWebsiteDataStore nonPersistentDataStore];if(![self isMiFi]){NSString*cfg=[[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:@{@"username":_config[@"username"]?:@"admin",@"password":_config[@"password"]?:@"",@"route":_route} options:0 error:nil] encoding:NSUTF8StringEncoding];NSString*js=[NSString stringWithFormat:@"(()=>{const c=%@;const t=setInterval(()=>{if(document.getElementById('login_app')&&typeof g_this!=='undefined'&&g_this?.formData){clearInterval(t);g_this.formData.LoginName=c.username;g_this.formData.LoginPwd=c.password;g_this.onSumit();}else if(location.pathname.includes('main.html')&&document.body){clearInterval(t);location.hash=c.route;}},350);setTimeout(()=>clearInterval(t),12000);})();",cfg];[c.userContentController addUserScript:[[WKUserScript alloc]initWithSource:js injectionTime:WKUserScriptInjectionTimeAtDocumentEnd forMainFrameOnly:YES]];}[c.userContentController addUserScript:[[WKUserScript alloc]initWithSource:@"document.documentElement.style.webkitTextSizeAdjust='100%';" injectionTime:WKUserScriptInjectionTimeAtDocumentEnd forMainFrameOnly:YES]];_web=[[WKWebView alloc]initWithFrame:CGRectZero configuration:c];_web.navigationDelegate=self;_web.translatesAutoresizingMaskIntoConstraints=NO;_web.customUserAgent=@"Mozilla/5.0 (iPhone; CPU iPhone OS 16_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.5 Mobile/15E148 Safari/604.1";[self.view addSubview:_web];[NSLayoutConstraint activateConstraints:@[[_web.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[_web.bottomAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.bottomAnchor],[_web.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[_web.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor]]];dispatch_group_t g=dispatch_group_create();for(NSHTTPCookie*cookie in _cookies){dispatch_group_enter(g);[c.websiteDataStore.httpCookieStore setCookie:cookie completionHandler:^{dispatch_group_leave(g);}];}dispatch_group_notify(g,dispatch_get_main_queue(),^{[self startLoad];});}
-(void)startLoad{[self reload];}
-(void)reload{NSString*u=[self isMiFi]?[NSString stringWithFormat:@"%@%@",_config[@"address"],[_route hasPrefix:@"/"]?_route:@"/index.html#home"]:[NSString stringWithFormat:@"%@/main.html#%@",_config[@"address"],_route];[_web loadRequest:[NSURLRequest requestWithURL:[NSURL URLWithString:u]]];}
-(void)close{if(_didClose)return;_didClose=YES;[_web stopLoading];[self dismissViewControllerAnimated:YES completion:^{if(self.onClose)self.onClose();}];}
-(void)webView:(WKWebView*)web decidePolicyForNavigationAction:(WKNavigationAction*)a decisionHandler:(void(^)(WKNavigationActionPolicy))done{NSURL*allowed=[NSURL URLWithString:_config[@"address"]];done([a.request.URL.host isEqual:allowed.host]?WKNavigationActionPolicyAllow:WKNavigationActionPolicyCancel);}
-(void)webView:(WKWebView*)web didFinishNavigation:(WKNavigation*)n{[_web evaluateJavaScript:@"document.documentElement.style.webkitTextSizeAdjust='100%'" completionHandler:nil];if([self isMiFi]){[_web evaluateJavaScript:@"(function(){var t=setInterval(function(){if(document.documentElement){clearInterval(t);document.documentElement.style.webkitTextSizeAdjust='100%';}},300);})()" completionHandler:nil];}}
@end